import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";

export default function CheckboxDisabled() {
  return (
    <div className="flex flex-col gap-group">
      <Field orientation="horizontal">
        <Checkbox disabled />
        <FieldLabel>Accept terms and conditions</FieldLabel>
      </Field>
      <Field orientation="horizontal">
        <Checkbox disabled defaultChecked />
        <FieldLabel>Enable notifications</FieldLabel>
      </Field>
      <Field orientation="horizontal">
        <Checkbox disabled indeterminate />
        <FieldLabel>Sync some folders</FieldLabel>
      </Field>
    </div>
  );
}

import ExampleCheckboxDisabled from "../examples/checkbox-disabled";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleCheckboxDisabled />
  </div>
);

export default Example;
